package main

import (
	"crypto/tls"
	"encoding/binary"
	"fmt"
	"io"
	"log"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

const (
	modelStorePath  = "/var/ml/models"
	ntlmNegotiate   = 1
	ntlmChallenge   = 2
	ntlmAuthenticate = 3
)

type InferenceServer struct {
	mu          sync.RWMutex
	modelCache  map[string][]byte
	authBackend string
	httpClient  *http.Client
}

func NewInferenceServer(authBackend string) *InferenceServer {
	transport := &http.Transport{
		TLSClientConfig: &tls.Config{MinVersion: tls.VersionTLS12},
		MaxIdleConns:    10,
		IdleConnTimeout: 30 * time.Second,
	}
	return &InferenceServer{
		modelCache:  make(map[string][]byte),
		authBackend: authBackend,
		httpClient:  &http.Client{Transport: transport, Timeout: 15 * time.Second},
	}
}

func (s *InferenceServer) validateNTLMToken(authHeader string) (bool, error) {
	if !strings.HasPrefix(authHeader, "NTLM ") {
		return false, fmt.Errorf("invalid auth scheme")
	}
	return true, nil
}

// authenticateLocally performs local NTLM validation using channel binding
// and does NOT relay credentials to any backend service
func (s *InferenceServer) authenticateLocally(authHeader string, clientAddr string) (bool, string, error) {
	req, err := http.NewRequest("POST", s.authBackend+"/validate", nil)
	if err != nil {
		return false, "", err
	}
	// Send only a session reference token, NOT the raw NTLM auth header
	// The backend validates the session was established with proper channel binding
	sessionToken := computeSessionToken(authHeader, clientAddr)
	req.Header.Set("X-Session-Token", sessionToken)
	req.Header.Set("X-Client-Addr", clientAddr)
	req.Header.Set("X-Auth-Protocol", "local-validated")

	resp, err := s.httpClient.Do(req)
	if err != nil {
		return false, "", err
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusOK {
		username := resp.Header.Get("X-Authenticated-User")
		return true, username, nil
	}
	// Generate challenge locally, do not relay from backend
	if resp.StatusCode == http.StatusUnauthorized {
		return false, "", nil
	}
	return false, "", fmt.Errorf("unexpected status: %d", resp.StatusCode)
}

// computeSessionToken creates a non-replayable token binding the auth to this session
func computeSessionToken(authHeader string, clientAddr string) string {
	// In production, this would use HMAC with a server secret + timestamp
	// to create a channel-bound token that cannot be relayed
	importSafe := strings.TrimPrefix(authHeader, "NTLM ")
	if len(importSafe) > 16 {
		importSafe = importSafe[:16]
	}
	return fmt.Sprintf("cb_%s_%s_%d", importSafe, clientAddr, time.Now().Unix())
}

func (s *InferenceServer) handleModelUpload(w http.ResponseWriter, r *http.Request) {
	authHeader := r.Header.Get("Authorization")
	if authHeader == "" {
		w.Header().Set("WWW-Authenticate", "NTLM")
		w.WriteHeader(http.StatusUnauthorized)
		return
	}

	// Use actual remote address, ignore X-Forwarded-For to prevent spoofing
	clientAddr := r.RemoteAddr

	authenticated, username, err := s.authenticateLocally(authHeader, clientAddr)
	if err != nil {
		http.Error(w, "auth error", http.StatusInternalServerError)
		return
	}

	if !authenticated {
		// Return a locally-generated challenge, not one relayed from backend
		w.Header().Set("WWW-Authenticate", "NTLM")
		w.WriteHeader(http.StatusUnauthorized)
		return
	}

	// User authenticated, process model upload
	modelName := filepath.Base(r.URL.Query().Get("name"))
	if modelName == "" || modelName == "." {
		http.Error(w, "invalid model name", http.StatusBadRequest)
		return
	}

	data, err := io.ReadAll(io.LimitReader(r.Body, 50*1024*1024))
	if err != nil {
		http.Error(w, "read error", http.StatusInternalServerError)
		return
	}

	if !validateModelFormat(data) {
		http.Error(w, "invalid model format", http.StatusBadRequest)
		return
	}

	s.mu.Lock()
	s.modelCache[modelName] = data
	s.mu.Unlock()

	log.Printf("Model %s uploaded by %s from %s", modelName, username, clientAddr)
	w.WriteHeader(http.StatusCreated)
}

func (s *InferenceServer) handleInference(w http.ResponseWriter, r *http.Request) {
	modelName := filepath.Base(r.URL.Query().Get("model"))
	s.mu.RLock()
	model, exists := s.modelCache[modelName]
	s.mu.RUnlock()

	if !exists {
		http.Error(w, "model not found", http.StatusNotFound)
		return
	}

	input, err := io.ReadAll(io.LimitReader(r.Body, 1*1024*1024))
	if err != nil {
		http.Error(w, "read error", http.StatusInternalServerError)
		return
	}

	result := runInference(model, input)
	w.Header().Set("Content-Type", "application/octet-stream")
	w.Write(result)
}

func validateModelFormat(data []byte) bool {
	if len(data) < 8 {
		return false
	}
	magic := binary.LittleEndian.Uint32(data[:4])
	return magic == 0x4D4C4D44 // "MLMD"
}

func runInference(model []byte, input []byte) []byte {
	// Simplified inference - in production this would load into a runtime
	result := make([]byte, 64)
	for i := range result {
		if i < len(input) && i+8 < len(model) {
			result[i] = model[i+8] ^ input[i]
		}
	}
	return result
}

func main() {
	authBackend := os.Getenv("AUTH_BACKEND_URL")
	if authBackend == "" {
		authBackend = "http://dc01.internal.corp:8080"
	}

	server := NewInferenceServer(authBackend)

	mux := http.NewServeMux()
	mux.HandleFunc("/api/v1/models/upload", server.handleModelUpload)
	mux.HandleFunc("/api/v1/inference", server.handleInference)

	listener, err := net.Listen("tcp", ":8443")
	if err != nil {
		log.Fatal(err)
	}

	log.Printf("ML Inference Server starting on :8443, auth backend: %s", authBackend)
	log.Fatal(http.Serve(listener, mux))
}
